//! The controller's CA: generated by the first replica that finds none,
//! kept in Secret `portail-controller-ca`, published in ConfigMap
//! `portail-controller-ca`; each replica issues its serving cert from it in
//! memory. Rotation is manual: delete the Secret, restart the controller.
//!
//! No certificate parser: the issuer is rebuilt from the fixed parameters
//! the CA was generated with plus its stored key, and checked by verifying
//! a leaf it issues against the stored CA certificate.

use std::fmt;
use std::sync::Arc;
use std::time::{Duration, SystemTime};

use arc_swap::ArcSwap;
use k8s_openapi::api::core::v1::{ConfigMap, Secret};
use k8s_openapi::ByteString;
use kube::api::{Api, ObjectMeta, Patch, PatchParams, PostParams};
use kube::Client;
use rcgen::{
    BasicConstraints, CertificateParams, DistinguishedName, DnType, ExtendedKeyUsagePurpose, IsCa,
    Issuer, KeyPair, KeyUsagePurpose, PKCS_ECDSA_P256_SHA256,
};
use rustls::client::danger::ServerCertVerifier;
use rustls::crypto::CryptoProvider;
use rustls::pki_types::pem::PemObject;
use rustls::pki_types::{CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer, ServerName, UnixTime};
use rustls::server::{ClientHello, ResolvesServerCert};
use rustls::sign::CertifiedKey;
use tokio_util::sync::CancellationToken;

use crate::kubernetes::naming;
use crate::logging::{error, info};

/// The Secret holding the CA and the ConfigMap publishing its certificate.
pub(crate) const CA_NAME: &str = "portail-controller-ca";
/// The kube-root-ca.crt ConfigMap's key, in both objects.
const CERT_KEY: &str = "ca.crt";
const KEY_KEY: &str = "ca.key";
const CA_COMMON_NAME: &str = "portail-controller-ca";

const DAY: Duration = Duration::from_secs(24 * 60 * 60);
// kubeadm's CA and leaf lifetimes, and its CertificateBackdate: a peer whose
// clock runs a little behind still accepts a cert issued a moment ago.
const CA_VALIDITY: Duration = Duration::from_secs(10 * 365 * DAY.as_secs());
const LEAF_VALIDITY: Duration = Duration::from_secs(365 * DAY.as_secs());
const BACKDATE: Duration = Duration::from_secs(5 * 60);
/// Re-issued at 2/3 of its life: cert-manager's default renewBefore.
const LEAF_RENEW_AFTER: Duration = Duration::from_secs(LEAF_VALIDITY.as_secs() * 2 / 3);
/// A failed re-issue leaves a third of the leaf's life: daily retries try
/// over a hundred times before it expires.
const LEAF_RETRY: Duration = DAY;

#[derive(Debug)]
pub(crate) enum CaError {
    /// The apiserver did not answer as needed: retry.
    Api(kube::Error),
    /// The stored CA cannot be used.
    Invalid(String),
}

impl fmt::Display for CaError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CaError::Api(e) => write!(f, "controller CA: {e}"),
            CaError::Invalid(why) => write!(
                f,
                "controller CA in Secret {CA_NAME}: {why}; delete the Secret to generate a new one"
            ),
        }
    }
}

impl std::error::Error for CaError {}

impl From<kube::Error> for CaError {
    fn from(e: kube::Error) -> Self {
        CaError::Api(e)
    }
}

/// The CA and this replica's serving cert.
pub(crate) struct ControllerCa {
    cert_pem: String,
    issuer: Issuer<'static, KeyPair>,
    /// The controller Service's in-cluster names.
    names: Vec<String>,
    provider: Arc<CryptoProvider>,
    serving: Arc<ServingCert>,
}

/// The current leaf for every handshake: a re-issue swaps it under live
/// listeners.
#[derive(Debug)]
struct ServingCert(ArcSwap<CertifiedKey>);

impl ResolvesServerCert for ServingCert {
    fn resolve(&self, _hello: ClientHello<'_>) -> Option<Arc<CertifiedKey>> {
        Some(self.0.load_full())
    }
}

/// Load the CA of `namespace` from its Secret, creating it when absent, and
/// publish its certificate; serve as Service `service`.
pub(crate) async fn load_or_create(
    client: &Client,
    namespace: &str,
    service: &str,
) -> Result<ControllerCa, CaError> {
    let secrets: Api<Secret> = Api::namespaced(client.clone(), namespace);
    let (cert_pem, key_pem) = match secrets.get_opt(CA_NAME).await? {
        Some(secret) => stored(&secret)?,
        None => {
            let (cert_pem, key_pem) = generate().map_err(|e| CaError::Invalid(e.to_string()))?;
            match secrets
                .create(&PostParams::default(), &ca_secret(&cert_pem, &key_pem))
                .await
            {
                Ok(_) => {
                    info!(
                        "Controller CA generated in Secret {}/{}",
                        namespace, CA_NAME
                    );
                    (cert_pem, key_pem)
                }
                // Another replica created it first: use theirs.
                Err(kube::Error::Api(e)) if e.code == 409 => stored(&secrets.get(CA_NAME).await?)?,
                Err(e) => return Err(e.into()),
            }
        }
    };
    let ca = ControllerCa::new(cert_pem, &key_pem, namespace, service)?;
    publish(client, namespace, &ca.cert_pem).await?;
    Ok(ca)
}

/// The Secret's PEMs.
fn stored(secret: &Secret) -> Result<(String, String), CaError> {
    let field = |key: &str| {
        let bytes = secret
            .data
            .as_ref()
            .and_then(|data| data.get(key))
            .ok_or_else(|| CaError::Invalid(format!("no {key}")))?;
        String::from_utf8(bytes.0.clone())
            .map_err(|_| CaError::Invalid(format!("{key} is not PEM")))
    };
    Ok((field(CERT_KEY)?, field(KEY_KEY)?))
}

fn ca_secret(cert_pem: &str, key_pem: &str) -> Secret {
    Secret {
        metadata: metadata(),
        // Opaque, not kubernetes.io/tls: a Gateway certificateRef never
        // resolves to it and the TLS Secret reflector never caches it.
        type_: Some("Opaque".into()),
        data: Some(
            [
                (
                    CERT_KEY.to_string(),
                    ByteString(cert_pem.as_bytes().to_vec()),
                ),
                (KEY_KEY.to_string(), ByteString(key_pem.as_bytes().to_vec())),
            ]
            .into(),
        ),
        ..Default::default()
    }
}

fn metadata() -> ObjectMeta {
    ObjectMeta {
        name: Some(CA_NAME.into()),
        labels: Some(
            [
                (naming::LABEL_NAME.to_string(), naming::NAME.to_string()),
                (
                    naming::LABEL_MANAGED_BY.to_string(),
                    naming::MANAGED_BY.to_string(),
                ),
            ]
            .into(),
        ),
        ..Default::default()
    }
}

/// The ConfigMap Unmanaged data planes read the CA from holds `cert_pem`.
async fn publish(client: &Client, namespace: &str, cert_pem: &str) -> Result<(), kube::Error> {
    let maps: Api<ConfigMap> = Api::namespaced(client.clone(), namespace);
    let published = |map: &ConfigMap| {
        map.data
            .as_ref()
            .and_then(|d| d.get(CERT_KEY))
            .is_some_and(|pem| pem == cert_pem)
    };
    let existing = match maps.get_opt(CA_NAME).await? {
        Some(map) => map,
        None => {
            let map = ConfigMap {
                metadata: metadata(),
                data: Some([(CERT_KEY.to_string(), cert_pem.to_string())].into()),
                ..Default::default()
            };
            match maps.create(&PostParams::default(), &map).await {
                Ok(_) => return Ok(()),
                Err(kube::Error::Api(e)) if e.code == 409 => maps.get(CA_NAME).await?,
                Err(e) => return Err(e),
            }
        }
    };
    if !published(&existing) {
        maps.patch(
            CA_NAME,
            &PatchParams::default(),
            &Patch::Merge(serde_json::json!({"data": {CERT_KEY: cert_pem}})),
        )
        .await?;
        info!(
            "Controller CA published in ConfigMap {}/{}",
            namespace, CA_NAME
        );
    }
    Ok(())
}

/// The parameters the CA certificate is generated with. Its issuer is
/// rebuilt from them, so they never change: a leaf's issuer name must equal
/// the stored certificate's subject.
fn ca_params() -> CertificateParams {
    let mut params = CertificateParams::default();
    params.distinguished_name = DistinguishedName::new();
    params
        .distinguished_name
        .push(DnType::CommonName, CA_COMMON_NAME);
    params.is_ca = IsCa::Ca(BasicConstraints::Constrained(0));
    params.key_usages = vec![
        KeyUsagePurpose::KeyCertSign,
        KeyUsagePurpose::CrlSign,
        KeyUsagePurpose::DigitalSignature,
    ];
    params
}

/// A new CA: certificate and key PEM.
fn generate() -> Result<(String, String), rcgen::Error> {
    let key = KeyPair::generate_for(&PKCS_ECDSA_P256_SHA256)?;
    let mut params = ca_params();
    let now = SystemTime::now();
    params.not_before = (now - BACKDATE).into();
    params.not_after = (now + CA_VALIDITY).into();
    let cert = params.self_signed(&key)?;
    Ok((cert.pem(), key.serialize_pem()))
}

impl ControllerCa {
    fn new(
        cert_pem: String,
        key_pem: &str,
        namespace: &str,
        service: &str,
    ) -> Result<Self, CaError> {
        let key =
            KeyPair::from_pem(key_pem).map_err(|e| CaError::Invalid(format!("{KEY_KEY}: {e}")))?;
        let ca_der = CertificateDer::from_pem_slice(cert_pem.as_bytes())
            .map_err(|e| CaError::Invalid(format!("{CERT_KEY}: {e}")))?;
        let issuer = Issuer::new(ca_params(), key);
        let svc = naming::controller_audience(service, namespace);
        let names = vec![svc.clone(), format!("{svc}.cluster.local")];
        let provider = Arc::new(rustls::crypto::aws_lc_rs::default_provider());
        let leaf = issue(&issuer, &names, &provider)
            .map_err(|e| CaError::Invalid(format!("issuing the serving cert: {e}")))?;
        verify(&ca_der, &leaf.cert[0], &names, &provider)?;
        Ok(ControllerCa {
            cert_pem,
            issuer,
            names,
            provider,
            serving: Arc::new(ServingCert(ArcSwap::from_pointee(leaf))),
        })
    }

    /// A new CA, not stored anywhere.
    #[cfg(test)]
    pub(super) fn generated(namespace: &str, service: &str) -> Self {
        let (cert, key) = generate().unwrap();
        ControllerCa::new(cert, &key, namespace, service).unwrap()
    }

    /// The CA certificate, PEM.
    #[cfg(test)]
    pub(crate) fn cert_pem(&self) -> &str {
        &self.cert_pem
    }

    /// The TLS config of the sync endpoint: HTTP/1.1, the current leaf.
    pub(crate) fn server_config(&self) -> Arc<rustls::ServerConfig> {
        let mut config = rustls::ServerConfig::builder_with_provider(self.provider.clone())
            .with_safe_default_protocol_versions()
            .expect("the aws-lc-rs provider supports the default protocol versions")
            .with_no_client_auth()
            .with_cert_resolver(self.serving.clone());
        config.alpn_protocols = vec![b"http/1.1".to_vec()];
        Arc::new(config)
    }

    /// Re-issue the serving cert at 2/3 of its life until `shutdown`.
    pub(crate) async fn keep_renewed(self, shutdown: CancellationToken) {
        let mut wait = LEAF_RENEW_AFTER;
        loop {
            tokio::select! {
                _ = shutdown.cancelled() => return,
                _ = tokio::time::sleep(wait) => {}
            }
            wait = match issue(&self.issuer, &self.names, &self.provider) {
                Ok(leaf) => {
                    self.serving.0.store(Arc::new(leaf));
                    info!("Controller serving cert re-issued");
                    LEAF_RENEW_AFTER
                }
                Err(e) => {
                    error!("Re-issuing the controller serving cert failed: {}", e);
                    LEAF_RETRY
                }
            };
        }
    }
}

/// A fresh serving cert for `names`, the first also its subject.
fn issue(
    issuer: &Issuer<'_, KeyPair>,
    names: &[String],
    provider: &CryptoProvider,
) -> Result<CertifiedKey, Box<dyn std::error::Error + Send + Sync>> {
    let mut params = CertificateParams::new(names.to_vec())?;
    params.distinguished_name = DistinguishedName::new();
    params
        .distinguished_name
        .push(DnType::CommonName, names[0].as_str());
    let now = SystemTime::now();
    params.not_before = (now - BACKDATE).into();
    params.not_after = (now + LEAF_VALIDITY).into();
    params.is_ca = IsCa::ExplicitNoCa;
    params.key_usages = vec![KeyUsagePurpose::DigitalSignature];
    params.extended_key_usages = vec![ExtendedKeyUsagePurpose::ServerAuth];
    params.use_authority_key_identifier_extension = true;
    let key = KeyPair::generate_for(&PKCS_ECDSA_P256_SHA256)?;
    let cert = params.signed_by(&key, issuer)?;
    let key_der = PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(key.serialize_der()));
    Ok(CertifiedKey::from_der(
        vec![cert.der().clone()],
        key_der,
        provider,
    )?)
}

/// `leaf` chains to the CA certificate `ca_der` for every one of `names`:
/// a stored key and certificate that do not belong together fail here, not
/// in every data plane.
fn verify(
    ca_der: &CertificateDer<'_>,
    leaf: &CertificateDer<'_>,
    names: &[String],
    provider: &Arc<CryptoProvider>,
) -> Result<(), CaError> {
    let mut roots = rustls::RootCertStore::empty();
    roots
        .add(ca_der.clone().into_owned())
        .map_err(|e| CaError::Invalid(format!("{CERT_KEY}: {e}")))?;
    let verifier = rustls::client::WebPkiServerVerifier::builder_with_provider(
        Arc::new(roots),
        provider.clone(),
    )
    .build()
    .map_err(|e| CaError::Invalid(e.to_string()))?;
    for name in names {
        let server_name = ServerName::try_from(name.clone())
            .map_err(|e| CaError::Invalid(format!("{name}: {e}")))?;
        verifier
            .verify_server_cert(leaf, &[], &server_name, &[], UnixTime::now())
            .map_err(|e| CaError::Invalid(format!("{CERT_KEY} and {KEY_KEY} do not match: {e}")))?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::{json, Value};
    use std::collections::HashMap;
    use std::sync::Mutex;

    const NS: &str = "portail-system";
    const SVC: &str = "portail-controller";

    /// Namespaced objects by path, created, read and merge-patched as the
    /// apiserver would. The first `held_gets` GETs wait for each other after
    /// reading, so that many replicas all read before any of them writes.
    struct FakeObjects {
        objects: Mutex<HashMap<String, Value>>,
        requests: Mutex<Vec<(String, String)>>,
        held_gets: Mutex<usize>,
        barrier: tokio::sync::Barrier,
    }

    impl FakeObjects {
        fn new(replicas: usize) -> Arc<Self> {
            Arc::new(Self {
                objects: Mutex::default(),
                requests: Mutex::default(),
                held_gets: Mutex::new(replicas),
                barrier: tokio::sync::Barrier::new(replicas.max(1)),
            })
        }

        fn status(code: u16, reason: &str) -> (u16, Value) {
            (
                code,
                json!({"kind": "Status", "apiVersion": "v1", "status": "Failure",
                       "message": reason, "reason": reason, "code": code}),
            )
        }

        async fn answer(&self, method: &str, path: &str, body: Value) -> (u16, Value) {
            self.requests
                .lock()
                .unwrap()
                .push((method.to_string(), path.to_string()));
            let reply = {
                let mut objects = self.objects.lock().unwrap();
                match method {
                    "GET" => objects
                        .get(path)
                        .map(|o| (200, o.clone()))
                        .unwrap_or_else(|| Self::status(404, "NotFound")),
                    "POST" => {
                        let item = format!("{path}/{}", body["metadata"]["name"].as_str().unwrap());
                        match objects.entry(item) {
                            std::collections::hash_map::Entry::Occupied(_) => {
                                Self::status(409, "AlreadyExists")
                            }
                            std::collections::hash_map::Entry::Vacant(slot) => {
                                slot.insert(body.clone());
                                (201, body)
                            }
                        }
                    }
                    "PATCH" => match objects.get_mut(path) {
                        Some(object) => {
                            for (k, v) in body["data"].as_object().unwrap() {
                                object["data"][k] = v.clone();
                            }
                            (200, object.clone())
                        }
                        None => Self::status(404, "NotFound"),
                    },
                    _ => Self::status(405, "MethodNotAllowed"),
                }
            };
            let held = method == "GET" && {
                let mut left = self.held_gets.lock().unwrap();
                let hold = *left > 0;
                *left = left.saturating_sub(1);
                hold
            };
            if held {
                self.barrier.wait().await;
            }
            reply
        }

        fn client(self: &Arc<Self>) -> Client {
            let fake = self.clone();
            let service = tower::service_fn(move |req: http::Request<kube::client::Body>| {
                let fake = fake.clone();
                async move {
                    let (parts, body) = req.into_parts();
                    let bytes = body.collect_bytes().await.unwrap_or_default();
                    let (code, reply) = fake
                        .answer(
                            parts.method.as_str(),
                            parts.uri.path(),
                            serde_json::from_slice(&bytes).unwrap_or(Value::Null),
                        )
                        .await;
                    Ok::<_, std::convert::Infallible>(
                        http::Response::builder()
                            .status(code)
                            .body(kube::client::Body::from(
                                serde_json::to_vec(&reply).unwrap(),
                            ))
                            .unwrap(),
                    )
                }
            });
            Client::new(service, NS)
        }

        fn object(&self, plural: &str) -> Option<Value> {
            let path = format!("/api/v1/namespaces/{NS}/{plural}/{CA_NAME}");
            self.objects.lock().unwrap().get(&path).cloned()
        }

        fn put(&self, plural: &str, object: Value) {
            let path = format!("/api/v1/namespaces/{NS}/{plural}/{CA_NAME}");
            self.objects.lock().unwrap().insert(path, object);
        }

        fn count(&self, method: &str, plural: &str) -> usize {
            self.requests
                .lock()
                .unwrap()
                .iter()
                .filter(|(m, p)| m == method && p.contains(&format!("/{plural}")))
                .count()
        }

        /// The stored Secret's CA certificate.
        fn secret_cert(&self) -> String {
            let b64 = self.object("secrets").unwrap()["data"][CERT_KEY]
                .as_str()
                .unwrap()
                .to_string();
            use base64::Engine;
            String::from_utf8(
                base64::engine::general_purpose::STANDARD
                    .decode(b64)
                    .unwrap(),
            )
            .unwrap()
        }

        fn published_cert(&self) -> String {
            self.object("configmaps").unwrap()["data"][CERT_KEY]
                .as_str()
                .unwrap()
                .to_string()
        }
    }

    fn secret_of(cert_pem: &str, key_pem: &str) -> Value {
        serde_json::to_value(ca_secret(cert_pem, key_pem)).unwrap()
    }

    #[tokio::test]
    async fn two_replicas_starting_together_end_with_one_ca() {
        let fake = FakeObjects::new(2);
        let client = fake.client();
        let (a, b) = tokio::join!(
            load_or_create(&client, NS, SVC),
            load_or_create(&client, NS, SVC)
        );
        let (a, b) = (a.unwrap(), b.unwrap());
        assert_eq!(fake.count("POST", "secrets"), 2, "both generated one");
        assert_eq!(a.cert_pem(), b.cert_pem());
        assert_eq!(fake.secret_cert(), a.cert_pem());
        assert_eq!(fake.published_cert(), a.cert_pem());
        let secret = fake.object("secrets").unwrap();
        assert_eq!(secret["type"], "Opaque");
    }

    #[tokio::test]
    async fn a_stored_ca_is_reused_and_a_stale_configmap_patched() {
        let fake = FakeObjects::new(0);
        let (cert, key) = generate().unwrap();
        fake.put("secrets", secret_of(&cert, &key));
        let (old, _) = generate().unwrap();
        fake.put(
            "configmaps",
            json!({"apiVersion": "v1", "kind": "ConfigMap",
                   "metadata": {"name": CA_NAME, "namespace": NS},
                   "data": {CERT_KEY: old}}),
        );

        let ca = load_or_create(&fake.client(), NS, SVC).await.unwrap();
        assert_eq!(ca.cert_pem(), cert);
        assert_eq!(fake.count("POST", "secrets"), 0);
        assert_eq!(fake.count("PATCH", "configmaps"), 1);
        assert_eq!(fake.published_cert(), cert);

        // Already published: nothing written.
        load_or_create(&fake.client(), NS, SVC).await.unwrap();
        assert_eq!(fake.count("PATCH", "configmaps"), 1);
        assert_eq!(fake.count("POST", "configmaps"), 0);
    }

    #[tokio::test]
    async fn a_secret_whose_cert_and_key_differ_is_refused() {
        let fake = FakeObjects::new(0);
        let (cert, _) = generate().unwrap();
        let (_, key) = generate().unwrap();
        fake.put("secrets", secret_of(&cert, &key));
        match load_or_create(&fake.client(), NS, SVC).await {
            Err(CaError::Invalid(why)) => assert!(why.contains("do not match"), "{why}"),
            Err(e) => panic!("{e}"),
            Ok(_) => panic!("a mismatched CA loaded"),
        }
        assert!(fake.object("configmaps").is_none(), "nothing published");
    }

    /// The issuer rebuilt from the fixed parameters and the stored key signs
    /// leaves that chain to the stored certificate, for both Service names,
    /// and to no other CA.
    #[test]
    fn a_rebuilt_issuer_signs_leaves_that_chain_to_the_stored_cert() {
        let (cert, key) = generate().unwrap();
        let ca = ControllerCa::new(cert.clone(), &key, NS, SVC).unwrap();
        assert_eq!(
            ca.names,
            [
                "portail-controller.portail-system.svc",
                "portail-controller.portail-system.svc.cluster.local"
            ]
        );
        let leaf = issue(&ca.issuer, &ca.names, &ca.provider).unwrap();
        let der = CertificateDer::from_pem_slice(cert.as_bytes()).unwrap();
        verify(&der, &leaf.cert[0], &ca.names, &ca.provider).unwrap();

        let other = CertificateDer::from_pem_slice(generate().unwrap().0.as_bytes()).unwrap();
        assert!(verify(&other, &leaf.cert[0], &ca.names, &ca.provider).is_err());
        let wrong_name = ["portail-controller.other.svc".to_string()];
        assert!(verify(&der, &leaf.cert[0], &wrong_name, &ca.provider).is_err());
    }

    #[test]
    fn leaves_are_reissued_at_two_thirds_of_their_life() {
        assert_eq!(LEAF_RENEW_AFTER.as_secs() * 3, LEAF_VALIDITY.as_secs() * 2);
        assert!(LEAF_RENEW_AFTER + LEAF_RETRY < LEAF_VALIDITY);
    }
}
